(function(window, document) {
  "use strict";

  // Minimal polyfills (only what we need)
  if (!Array.prototype.includes) {
    Array.prototype.includes = function(searchElement /*, fromIndex*/ ) {
      var O = Object(this);
      var len = parseInt(O.length, 10) || 0;
      if (len === 0) return false;
      var n = parseInt(arguments[1], 10) || 0;
      var k = Math.max(n >= 0 ? n : len - Math.abs(n), 0);
      while (k < len) {
        var current = O[k];
        if (current === searchElement || (Number.isNaN && Number.isNaN(current) && Number.isNaN(searchElement))) {
          return true;
        }
        k++;
      }
      return false;
    };
  }

  // -- state
  var animating = false;
  var loggedIn = false;
  var intervalStatus = null;
  var $errorContainer = document.querySelector(".error-container");
  var hotspotConfig = window.hotspotConfig || {}; // if present server may set this
  var un = ""; // last status JSON passed to onStatusQuery

  // --- helper DOM selectors
  function $id(id) {
    return document.getElementById(id);
  }

  function $qs(sel) {
    return document.querySelector(sel);
  }

  function $qsa(sel) {
    return Array.prototype.slice.call(document.querySelectorAll(sel));
  }

  // --- errors / popup
  function showErrorPopup() {
    if (!$errorContainer) return;
    $errorContainer.classList.add("active");
    setTimeout(function() {
      $errorContainer.classList.add("zoom");
    }, 10);
  }

  function hideErrorPopup() {
    if (!$errorContainer) return;
    $errorContainer.classList.remove("active");
    $errorContainer.classList.remove("zoom");
  }

  function getBaseSpeed(sspeed) {
    if (!sspeed) return "";
    return sspeed.replace(/_Uoff/gi, "").replace(/_+$/, "");
  }

  function isUoffActive(sspeed) {
    return !!(sspeed && sspeed.indexOf("_Uoff") >= 0);
  }

  // --- helper formatters
  function toArabicBytes(num) {
    num = Number(num) || 0;
    if (num < 1024) return num + " بايت ";
    if (num < 1048576) return Math.round(num / 1024) + " كيلوبايت ";
    return Math.round(num / 1048576) + " ميجابايت ";
  }

  function hideHalfCard(s) {
    if (!s) return "";
    if (s.toLowerCase().indexOf("t-") >= 0) return "تجربة مجانية";
    if (s.indexOf(":") >= 0) return "اشتراك";
    var t = Math.ceil(s.length / 2);
    return s.substring(0, t) + "*".repeat(t);
  }

  function toArabicError(err) {
    var mapping = {
      "user¬ found": "أن هذا الحساب غير موجود أو قد انتهت صلاحية ، حاول مرة اخرى",
      "simultaneous session limit reached|no more sessions are allowed": "المعذرة ، هذا الكرت مستخدم حالياً في جهاز آخر",
      "invalid password": "تاكد من كتابة كلمة المرور بشكل صحيح",
      "uptime limit reached|No more online time|uptime limit": "عذراً لقد انتهى الوقت المتاح لك",
      "traffic limit|transfer limit reached": "لقد انتهى رصيد هذا الحساب",
      "invalid username or password|not found": "أسم المستخدم أو كلمة المرور غير صحيحة، الرجاء المحاولة مرة اخرى",
      "no valid profile found": "لقد انتهت صلاحية هذا الكرت",
      "invalid Calling-Station-Id": "هذا الحساب مقترن بجهاز آخر!",
      "server&is¬&responding": "هذا الحساب غير موجود, يرجى التأكد والمحاولة مرة اخرى",
      "web&browser&did¬&send": "يرجى محاولة ادخال الكرت مرة اخرى",
      "allowed to log in from this MAC": "لايحق لك استخدام هذا الكرت, الكرت محجوز لمستخدم اخر!"
    };
    var defaultMsg = "حصل خطأ: " + err;

    function includesAny(pattern) {
      return pattern.split("|").some(function(p) {
        return err.includes(p);
      });
    }
    for (var patt in mapping) {
      if (patt.indexOf("&") >= 0) {
        var parts = patt.split("&");
        var ok = parts.every(function(p) {
          return err.includes(p);
        });
        if (ok) return mapping[patt];
      } else if (patt.indexOf("|") >= 0) {
        if (includesAny(patt)) return mapping[patt];
      } else {
        if (err.includes(patt)) return mapping[patt];
      }
    }
    return defaultMsg;
  }

  // --- network/xhr helpers
  function getRequest(url) {
    if (!url) return;
    if (window.location.protocol === "file:") {
      showLoginPage();
      return;
    }
    var xhr = new XMLHttpRequest();
    xhr.open("GET", url, true);
    xhr.onreadystatechange = function() {
      if (xhr.readyState !== 4) return;
      var text = xhr.responseText || "";
      try {
        var obj = JSON.parse(text);
        if (obj && obj.action && typeof window[obj.action] === "function") {
          window[obj.action](obj);
          return;
        }
      } catch (e) {
        // not JSON — fallback handling
      }
      // fallback: if status endpoint returned something unexpected, revert to login
      if (url.indexOf("/status?") >= 0) {
        loggedIn = false;
        hideStatusPage();
        showLoginPage();
      }
    };
    xhr.send();
  }

  // HLogin and Ulogin wrappers used by older code
  function HLogin(username, password) {
    if (!username) return;
    getRequest("/login?username=" + encodeURIComponent(username) + "&password=" + encodeURIComponent(password) + "&var=callBack");
  }

  function Ulogin(username, password, domain) {
    var suffix = "";
    if (domain) suffix = "&domain=" + encodeURIComponent(domain);
    getRequest("/login?username=" + encodeURIComponent(username) + "&password=" + encodeURIComponent(password) + "&var=callBack" + suffix);
  }

  // --- login flow (vouchers) called from UI
  function userLogin() {
    var username = (document.login && document.login.username && document.login.username.value || "").trim();
    if (!username) {
      var errEl = $id("error");
      if (errEl) {
        errEl.innerText = "يرجى إدخال الكرت";
        showErrorPopup();
      }
      animating = false;
      return;
    }
    var radios = document.getElementsByName("domain");
    var speedValue = "";
    for (var i = 0; i < radios.length; i++) {
      if (radios[i].checked) {
        speedValue = radios[i].value;
        break;
      }
    }
    if (!speedValue) {
      var errbox = $id("error-msg");
      if (errbox) errbox.style.display = "block";
      animating = false;
      return;
    }
    // MikroTik voucher login: username only; password empty
    HLogin(username, "");
    // Save selected speed locally for UI
    try {
      localStorage.setItem("selectedSpeed", speedValue);
    } catch (e) {}
  }

  // --- logout
  function userLogout(eraseCookie) {
    var url = eraseCookie ? "/logout?erase-cookie=yes&var=callBack" : "/logout?var=callBack";
    getRequest(url);
  }

  // --- UI show/hide helpers
  function hideLoginPage() {
    var el = $id("login");
    if (el) {
      el.style.display = "none";
      el.classList.add("inactive");
    }
  }

  function hideStatusPage() {
    var el = $id("status");
    if (el) {
      el.style.display = "none";
      el.classList.remove("active");
    }
  }

  function showLoginPage() {
    var el = $id("login");
    if (el) {
      populateSelectWithOptions();
      el.style.visibility = "visible";
      el.style.display = "block";
      getComputedStyle(el).top;
      el.classList.remove("inactive");
    }
  }

  function showStatusPage() {
    var s = $id("status");
    if (s) {
      s.style.display = "block";
      s.classList.add("active");
    }
  }

  // --- on login success / error callbacks (expected by server JSON)
  function onLoggedIn(resp) {
    loggedIn = true;
    try {
      remember();
    } catch (e) {}
    // hide login
    var loginEl = document.getElementById("login");
    if (loginEl) loginEl.classList.add("inactive");
    // show status
    var st = document.getElementById("status");
    if (st) {
      st.style.display = "block";
      st.classList.add("active");
    }
    window.scrollTo({
      top: 0,
      behavior: "smooth"
    });
    if (resp != null) {
      resetCounter && resetCounter();
      startStatusQuery();
    }
  }

  function onLoggedOut() {
    loggedIn = false;
  }

  function onLoginError(resp) {
    // resp expected: { error: "..." }
    try {
      document.login.reset();
    } catch (e) {}
    setTimeout(function() {
      var btn = document.querySelector(".login-submit");
      if (btn) {
        btn.classList.remove("success");
        btn.classList.remove("processing");
      }
    }, 500);
    animating = false;
    if (!resp || !resp.error) return;
    if ((resp.error || "").includes("already authorizing, retry later")) return;
    var errText = toArabicError(resp.error || "");
    var errEl = $id("error");
    if (errEl) errEl.innerText = errText;
    showErrorPopup();
    if (hotspotConfig["enable-hot-blocker"]) {
      var t = incrementCounter && incrementCounter(resp); // safe call
      checkFailsCount && checkFailsCount(resp, t);
    }
    clearCookies && clearCookies();
  }

  // Expose these globally for server callbacks
  window.getRequest = getRequest;
  window.HLogin = HLogin;
  window.Ulogin = Ulogin;
  window.userLogin = userLogin;
  window.userLogout = userLogout;
  window.onLoggedIn = onLoggedIn;
  window.onLoggedOut = onLoggedOut;
  window.onLoginError = onLoginError;

  // --- status handling from server JSON
  function onStatusQuery(obj) {
    // expected a JSON object with keys that map to element ids
    try {
      un = obj;
      if (obj.logged_in) {
        for (var k in obj) {
          if (!obj.hasOwnProperty(k)) continue;
          var v = obj[k];
          if (typeof v === "string" && k !== "logged_in") {
            var el = document.getElementById(k);
            if (!el) continue;
            if (v === "") {
              var fallback = document.querySelector("[" + k + "]");
              if (fallback) el.innerText = fallback.innerText || "";
            } else {
              if (k === "username") el.innerText = hideHalfCard(v);
              else if (k.indexOf("bytes") !== -1) el.innerText = toArabicBytes(v);
              else el.innerText = v;
            }
          }
        }
      } else {
        loggedIn = false;
      }
      // optional additional display logic (e.g., free card detection)
      try {
        if (obj && obj.username && obj.mac) {
          if (obj.username.includes(obj.mac.split("%3A").join(":"))) {
            // do nothing special for now; kept for parity with original
          }
        }
      } catch (e) {}
    } catch (e) {
      console.error("onStatusQuery parse error", e);
    }
  }
  window.onStatusQuery = onStatusQuery;

  // --- status poller (1s) that requests /status?var=callBack
  function startStatusQuery() {
    if (intervalStatus || !loggedIn) return;
    intervalStatus = setInterval(function() {
      if (!loggedIn) {
        clearInterval(intervalStatus);
        intervalStatus = null;
        return;
      }
      try {
        getRequest("/status?var=callBack");
      } catch (e) {}
    }, 1000);
    // initial request
    getRequest("/status?var=callBack");
  }
  window.startStatusQuery = startStatusQuery;

  // --- update UI features: speed toggle (expand / setSpeed)
  var isOpen = false;

  function expand(event) {
    if (event && event.stopPropagation) event.stopPropagation();
    var speedsContainer = document.querySelector(".speeds");
    var menu = document.getElementById("spdtgl-menu");
    if (!speedsContainer || !menu) return;
    if (!isOpen) {
      speedsContainer.classList.add("expanded");
      menu.style.transform = "scale(2)";
      isOpen = true;
    } else {
      speedsContainer.classList.remove("expanded");
      menu.style.transform = "scale(0)";
      isOpen = false;
    }
  }

  function setSpeed(name, value) {
    var speedText = document.getElementById("sspeed");
    if (speedText) speedText.innerText = name;

    var username = un && un.username ? un.username : "";
    if (!username) {
      var errEl = document.getElementById("error");
      if (errEl) errEl.innerText = "هذا المتصفح لا يدعم التغيير";
      showErrorPopup();
      setTimeout(function() {
        expand();
      }, 300);
      return;
    }
    // Keep Uoff suffix if the toggle is currently ON
    var updateToggle = document.getElementById("updatechange");
    var suffix = (updateToggle && !updateToggle.checked) ? "_Uoff" : "";

    getRequest("/logout?var=callBack");
    setTimeout(function() {
      Ulogin(username, "", value + suffix);
    }, 600);

    setTimeout(function() {
      expand();
    }, 300);
  }
  window.expand = expand;
  window.setSpeed = setSpeed;

  // close speed menu on outside click
  document.addEventListener("click", function(ev) {
    var menu = document.getElementById("spdtgl-menu");
    var speedsContainer = document.querySelector(".speeds");
    if (isOpen && menu && !menu.contains(ev.target) && speedsContainer && !speedsContainer.contains(ev.target)) {
      expand();
    }
  });

  // --- update change toggle handling
  // --- update change toggle handling
  (function() {
    var up = document.getElementById("updatechange");
    var ut = document.getElementById("update");
    if (!up) return;

    // Sync checkbox to reflect actual current login state on page load
    if (un && un.sspeed) {
      up.checked = !isUoffActive(un.sspeed);
      if (ut) ut.innerText = up.checked ? "تم التفعيل" : "تم الإيقاف";
    }

    up.addEventListener("change", function() {
      var username = un && un.username ? un.username : "";
      var speed = getBaseSpeed(un && un.sspeed ? un.sspeed : "");

      if (!username || !speed) {
        var errEl = document.getElementById("error");
        if (errEl) errEl.innerText = "هذا المتصفح لا يدعم التغيير";
        showErrorPopup();
        return;
      }

      var suffix = up.checked ? "" : "_Uoff";
      if (ut) ut.innerText = up.checked ? "تم التفعيل" : "تم الإيقاف";

      getRequest("/logout?var=callBack");
      setTimeout(function() {
        Ulogin(username, "", speed + suffix);
      }, 600);
      showErrorPopup();
    });
  })();

  // --- chupdate checkbox (if exists)
  (function() {
    var chupdateEl = $id("chupdate");
    if (!chupdateEl) return;
    chupdateEl.addEventListener("change", function(e) {
      try {
        var t = $id("error");
        window.f = false;
        if (e.target.checked) {
          if (t) t.innerText = " تم اختيار أيقاف المتجر و التحديثات *لن يعمل متجر التطبيقات و يمكنك تغيير ذلك لاحقا*";
          e.target.value = "_Uoff";
        } else {
          if (t) t.innerText = "تم اختيار تفعيل المتجر و التحديثات ";
          e.target.value = "";
        }
        showErrorPopup();
      } catch (err) {
        console.error("chupdate handler error:", err);
      }
    });
  })();

  // --- QR scanner wiring (html5-qrcode)
  (function() {
    var modal = $id("scanner-modal");
    var startBtn = $id("start-scan");
    var closeBtn = $id("close-scan");
    var readerId = "reader";
    var instance = null;
    var cfg = {
      fps: 10,
      qrbox: 250
    };

    function create() {
      if (instance) return instance;
      if (typeof Html5Qrcode === "undefined") return null;
      try {
        instance = new Html5Qrcode(readerId);
        return instance;
      } catch (e) {
        console.warn(e);
        return null;
      }
    }
    async function stopScanner() {
      if (!instance) {
        if (modal) modal.style.display = "none";
        return;
      }
      try {
        await instance.stop();
        instance.clear();
      } catch (e) {}
      if (modal) modal.style.display = "none";
    }
    async function startScanner() {
      instance = create();
      if (!instance) return;
      if (modal) modal.style.display = "flex";
      try {
        await instance.start({
          facingMode: "environment"
        }, cfg, function(decodedText) {
          try {
            alert("Scanned: " + decodedText);
          } catch (e) {}
          stopScanner();
        }, function(err) {
          // ignore decode errors
        });
      } catch (e) {
        console.error("Camera start error:", e);
        if (modal) modal.style.display = "none";
      }
    }
    if (startBtn) startBtn.addEventListener("click", function(e) {
      e.stopPropagation();
      startScanner();
    });
    if (closeBtn) closeBtn.addEventListener("click", function(e) {
      e.stopPropagation();
      stopScanner();
    });
    if (modal) modal.addEventListener("click", function(ev) {
      if (ev.target === modal) stopScanner();
    });
    // export for debug
    window.__html5QrCodeInstance = instance;
  })();

  // --- WhatsApp dialog wiring
  (function() {
    var toggle = $id("wa-toggle-btn");
    var closeBtn = $id("x-btn");
    var dialog = document.querySelector(".wa-dialog");
    var adminBtns = $qsa(".wa-admin-btn");
    var waText = $id("wa-text");

    function toggleHandler(e) {
      e && e.stopPropagation && e.stopPropagation();
      if (!dialog) return;
      dialog.classList.toggle("open");
    }

    function closeHandler(e) {
      e && e.stopPropagation && e.stopPropagation();
      if (!dialog) return;
      dialog.classList.remove("open");
    }

    function adminClick(e) {
      adminBtns.forEach(function(b) {
        b.classList.remove("active");
      });
      this.classList.add("active");
    }

    function outsideClick(e) {
      if (!dialog) return;
      if (dialog.classList.contains("open") && !dialog.contains(e.target) && toggle && !toggle.contains(e.target)) dialog.classList.remove("open");
    }
    if (toggle) {
      toggle.removeEventListener("click", toggleHandler);
      toggle.addEventListener("click", toggleHandler);
    }
    if (closeBtn) {
      closeBtn.removeEventListener("click", closeHandler);
      closeBtn.addEventListener("click", closeHandler);
    }
    if (adminBtns && adminBtns.length) adminBtns.forEach(function(b) {
      b.removeEventListener("click", adminClick);
      b.addEventListener("click", adminClick);
    });
    document.removeEventListener("click", outsideClick);
    document.addEventListener("click", outsideClick);

    // redirect to whatsapp
    window.redirectTowa = function() {
      try {
        var ua = navigator.userAgent || navigator.vendor || window.opera;
        var active = document.querySelector(".wa-admin-btn.active");
        var phoneNumber = active ? active.getAttribute("data-phone") : "905413646996";
        phoneNumber = phoneNumber.replace(/[\s()+-]/g, "");
        var message = waText ? waText.value : "";
        message = encodeURIComponent(message || "");
        var isMobile = /android|iphone|ipad|ipod/i.test(ua);
        var url = isMobile ? ("whatsapp://send?phone=" + phoneNumber + "&text=" + message) : ("https://web.whatsapp.com/send?phone=" + phoneNumber + "&text=" + message);
        window.open(url, "_blank");
      } catch (e) {
        console.error("redirectTowa error", e);
      }
    };
  })();

  // --- flickity safe init: keep radio sync working
  (function() {
    var elem = document.querySelector(".ht-main-csl");
    if (!elem) return;
    var flkty = (window.Flickity && Flickity.data && Flickity.data(elem)) || null;
    if (!flkty && window.Flickity) {
      try {
        var opts = {};
        var raw = elem.getAttribute("data-flickity") || "{}";
        opts = JSON.parse(raw);
        flkty = new Flickity(elem, opts);
      } catch (e) {
        flkty = null;
      }
    }
    if (!flkty) return;
    var radios = Array.prototype.slice.call(document.querySelectorAll(".ht-cekb"));

    function setActiveRadio(index) {
      if (!radios.length) return;
      radios.forEach(function(r) {
        r.checked = false;
      });
      if (typeof index === "number" && radios[index]) radios[index].checked = true;
    }
    radios.forEach(function(r, i) {
      r.addEventListener("change", function() {
        if (!this.checked) return;
        if (flkty && typeof flkty.select === "function") flkty.select(i);
      });
    });
    try {
      flkty.on("select", function() {
        setActiveRadio(flkty.selectedIndex);
      });
    } catch (e) {}
    setActiveRadio(typeof flkty.selectedIndex === "number" ? flkty.selectedIndex : 0);
  })();

  // --- small UI: bbbtn open/close
  (function() {
    var bbbtn = $qs(".bbbtn");
    var front = $qs(".bbbtn-front");
    var closeIcon = $qs(".close-icon");
    var cancel = $qs(".cancel-bbbtn");
    if (!bbbtn || !front) return;
    front.addEventListener("click", function(e) {
      var rect = bbbtn.getBoundingClientRect();
      var my = e.clientY - rect.top;
      var direction = (my < bbbtn.offsetHeight / 2) ? "top" : "bottom";
      bbbtn.setAttribute("data-direction", direction);
      bbbtn.classList.add("is-open");
    });
    if (closeIcon) closeIcon.addEventListener("click", function(e) {
      e.stopPropagation();
      bbbtn.classList.remove("is-open");
    });
    if (cancel) cancel.addEventListener("click", function(e) {
      e.stopPropagation();
      bbbtn.classList.remove("is-open");
    });
    document.addEventListener("click", function(e) {
      if (bbbtn.classList.contains("is-open") && !bbbtn.contains(e.target)) bbbtn.classList.remove("is-open");
    });
  })();

  // --- interactive login wiring: ensure #submit-btn triggers userLogin safely
  (function() {
    var submitBtn = $id("submit-btn");
    if (!submitBtn) return;
    submitBtn.addEventListener("click", function(ev) {
      // The form-level interception in index.html also handles immediate UI.
      // Here we call userLogin to preserve legacy flow (server-side login via /login?...)
      try {
        if (animating) return;
        animating = true;
        userLogin && userLogin();
      } catch (e) {
        console.error(e);
        animating = false;
      }
    });
  })();

  // --- small helpers (exposed for compatibility)
  window.showErrorPopup = showErrorPopup;
  window.hideErrorPopup = hideErrorPopup;

  // --- countdown/time UI (safe)
  (function() {
    try {
      var span = document.querySelector("[count-down-span]");
      var raw = span ? (span.innerText || "") : "";
      var totalSeconds = parseInt(raw, 10) || 0;

      function format(n) {
        return n < 10 ? "0" + n : "" + n;
      }

      function tick() {
        if (totalSeconds <= 0) {
          window.location.reload();
          return;
        }
        var d = Math.floor(totalSeconds / (3600 * 24));
        var h = Math.floor((totalSeconds % (3600 * 24)) / 3600);
        var m = Math.floor((totalSeconds % 3600) / 60);
        var s = totalSeconds % 60;
        var daysEl = $id("days"),
          hoursEl = $id("hours"),
          minutesEl = $id("minutes"),
          secEl = $id("seconds");
        if (daysEl) daysEl.textContent = format(d);
        if (hoursEl) hoursEl.textContent = format(h);
        if (minutesEl) minutesEl.textContent = format(m);
        if (secEl) {
          var formatted = format(s);
          if (secEl.textContent !== formatted) {
            secEl.textContent = formatted;
            secEl.classList.remove("pulse-active");
            void secEl.offsetWidth;
            secEl.classList.add("pulse-active");
          }
        }
        totalSeconds--;
      }
      if (totalSeconds > 0) {
        setInterval(tick, 1000);
        tick();
      } else {
        document.querySelectorAll(".segment-value").forEach(function(el) {
          el.textContent = "00";
        });
      }
    } catch (e) {}
  })();

  // --- borrow confirm dialog (kept)
  window.Confirm = {
    open: function(opt) {
      var html = '\n            <div class="confirm">\n                <div class="confirm__window">\n                    <div class="confirm__titlebar">' + (opt.title || "") + '</div>\n                    <div class="confirm__content">' + (opt.msg || "") + '</div>\n                    <div class="confirm__buttons">\n                        <button class="confirm__btn" id="c_can">إلغاء</button>\n                        <button class="confirm__btn confirm__btn--ok" id="c_ok">تأكيد</button>\n                    </div>\n                </div>\n            </div>';
      document.body.insertAdjacentHTML("beforeend", html);
      var el = document.querySelector(".confirm");
      var ok = document.getElementById("c_ok");
      var can = document.getElementById("c_can");
      if (ok) ok.onclick = function() {
        opt.onok && opt.onok();
        el.remove();
      };
      if (can) can.onclick = function() {
        el.remove();
      };
    }
  };
  window.askBorrow = function() {
    window.Confirm.open({
      title: "طلب خدمة سلفني",
      msg: "هل ترغب بتفعيل خدمة (سلفني) الآن بقيمة (50M)؟ سيتم خصم قيمة السلفة تلقائيا في تسجيل دخولك القادم.",
      onok: function() {
        window.location.href = "$(link-login-only)?dst=$(link-orig-esc)&username=trial";
      }
    });
  };

  // --- initial safe wiring run (DOMContentLoaded)
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function() {
      // nothing else here - main handlers are attached above
    });
  }

})(window, document);

// === Fix tbtn buttons ===
// Select elements - targeting by the attribute [parent-id] instead of a class
const loginMenu = document.getElementById('login');
const navButtons = document.querySelectorAll('[parent-id]'); // <-- MAGIC HAPPENS HERE
const backButtons = document.querySelectorAll('.goback');
const allApps = document.querySelectorAll('.app');

// This loop still works flawlessly regardless of the button's class name
navButtons.forEach(button => {
  button.addEventListener('click', () => {
    const targetId = button.getAttribute('parent-id');
    const targetApp = document.getElementById(targetId);

    if (targetApp) {
      allApps.forEach(app => app.classList.remove('active'));
      loginMenu.classList.add('inactive');
      targetApp.classList.add('active');
    }
  });
});

// Setup back buttons
backButtons.forEach(button => {
  button.addEventListener('click', () => {
    loginMenu.classList.remove('inactive');
    allApps.forEach(app => app.classList.remove('active'));
  });
});

// speed btn

function updateDisplay(label, color) {
  var displayBtn = document.getElementById("selection-display");

  // Update text in the dynamic button
  displayBtn.innerHTML = "Selected: " + label;

  // Apply the color to the dynamic button's CSS variable
  displayBtn.style.setProperty('--glow-color', color);
  displayBtn.style.backgroundColor = color;
  displayBtn.style.boxShadow = "0 0 20px " + color;

  // Hide error if visible
  document.getElementById("error-msg").style.display = "none";
}


function onStatusQuery(data) {
  const loginMenu = document.getElementById('login');
  const statusApp = document.getElementById('status');

  if (data.logged_in === "yes") {
    // 1. Switch the View: Hide login, Show status
    if (loginMenu && !loginMenu.classList.contains('inactive')) {
      loginMenu.classList.add('inactive');
      loginMenu.style.display = 'none';
    }
    if (statusApp && !statusApp.classList.contains('active')) {
      statusApp.classList.add('active');
      statusApp.style.display = 'block';
    }

    // 2. Sync the Live Data
    // We map the MikroTik variables from your status.html JSON to your HTML IDs
    const mappings = {
      'bytes_out': formatBytes(data.bytes_out),
      'bytes_in': formatBytes(data.bytes_in),
      'remain_bytes_total': formatBytes(data.remain_bytes_total),
      'session_time_left': data.session_time_left,
      'sspeed': data.sspeed
    };

    for (let id in mappings) {
      let el = document.getElementById(id);
      if (el) el.innerText = mappings[id];
    }
  } else {
    // If not logged in, ensure we are on the login page
    if (loginMenu && loginMenu.classList.contains('inactive')) {
      loginMenu.classList.remove('inactive');
      loginMenu.style.display = 'block';
      statusApp.classList.remove('active');
      statusApp.style.display = 'none';
    }
  }
}

// Simple helper to make bytes readable (MB/GB)
function formatBytes(bytes) {
  if (!bytes || bytes == 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

function setActive(clickedBtn) {
  // Remove the active class from all buttons
  document.querySelectorAll('.neon-btn').forEach(btn => {
    btn.classList.remove('active');
  });

  // Add the active class only to the clicked button
  clickedBtn.classList.add('active');
} 